    - MIDI note number formula: 12*(octave+1) + note_index (C=0,...B=11)
    """
    note_map_sharp = {
        'C': 0, 'C#': 1, 'D': 2, 'D#': 3, 'E': 4, 'F': 5,
        'F#': 6, 'G': 7, 'G#': 8, 'A': 9, 'A#': 10, 'B': 11
    }
