def maximum(arr, k):
    if k == 0:
        return []
    counts = {}
    for num in arr:
        counts[num] = counts.get(num, 0) + 1
    # Sort unique numbers descending
    unique_nums = sorted(counts.keys(), reverse=True)
    result = []
    for num in unique_nums:
        result.extend([num] * counts[num])
        if len(result) >= k:
            result = result[:k]
            break
    return sorted(result)

